const data = $input.first().json ?? {};
const config = $('Configuration (EDIT ME)').first().json;
const execution = data.execution ?? {};
const error = execution.error ?? data.trigger?.error ?? {};
const string = value => typeof value === 'string' ? value : '';
// Redact before truncating so even a token crossing the limit is removed.
const clean = (value, limit = 200) => string(value)
  .replace(/\bX-Api-Key\s*[:=]\s*(?:"[^"\r\n]*"|'[^'\r\n]*'|[^\s,;]+)/gi, 'X-Api-Key: [REDACTED]')
  .replace(/\bBearer\s+[^\s,;"']+/gi, 'Bearer [REDACTED]')
  .replace(/[\r\n\t]+/g, ' ').slice(0, limit);
const workflow = clean(data.workflow?.name) || 'Unknown workflow';
const node = clean(execution.lastNodeExecuted || error.node?.name) || 'Unknown node';
const message = clean([string(error.name), string(error.message) || string(error.cause?.message)]
  .filter(Boolean).join(': '), 500) || 'Unknown error';
const id = typeof execution.id === 'number' ? String(execution.id) : string(execution.id);
const safeId = /^[A-Za-z0-9_-]{1,80}$/.test(id) ? id : '';
const base = string(config.n8nBaseUrl).trim().replace(/\/+$/, '');
let link = '';
// Only a configured HTTP(S) base and execution paths; never mail URL credentials/query strings.
if (/^https?:\/\/(?:[a-z0-9.-]+|\[[0-9a-f:]+\])(?::\d{1,5})?(?:\/[a-z0-9_~./%-]*)?$/i.test(base)) {
  const url = string(execution.url);
  const path = url.startsWith(base + '/') ? url.slice(base.length) : '';
  if (/^\/(?:workflow\/[A-Za-z0-9_-]+\/)?executions?\/[A-Za-z0-9_-]+$/.test(path)) link = url;
  else if (safeId) link = `${base}/executions/${safeId}`;
}
const lines = [
  `Workflow: ${workflow}`, `Node: ${node}`, `Error: ${message}`,
  `Time (UTC): ${new Date().toISOString()}`,
];
if (safeId) lines.push(`Execution ID: ${safeId}`);
if (link) lines.push(`Execution: ${link}`);
// Explicit allowlist: no input/output data, headers, stack traces or error context.
return [{ json: {
  fromEmail: config.alertEmailFrom, toEmail: config.alertEmailTo,
  subject: `[n8n error] ${workflow}`, text: lines.join('\n'),
} }];
